/bin/bash -lc "python - <<'PY'
import requests
for repo in ['openpyxl','python']:
    url=f'https://quay.io/api/v1/repository/biocontainers/{repo}/tag/?limit=20'
    try:
        r=requests.get(url, timeout=20)
        print('repo',repo,'status',r.status_code)
        if r.ok:
            tags=[t['name'] for t in r.json().get('tags',[])[:10]]
            print(tags)
        else:
            print(r.text[:200])
    except Exception as e:
        print('err',repo,e)
PY"

